import vision.gears.webgpumath.*

// The look of a surface: the shaders, the values of their "material" uniforms
// and textures, and the render state.
class Material(vertexShader : Shader, fragmentShader : Shader) : UniformProvider("material") {

  // the pipelines made from the two shaders, shared by all materials with the same two shaders
  private val template = PipelineTemplate.of(vertexShader.device,
    vertexShader.module, vertexShader.reflection,
    fragmentShader.module, fragmentShader.reflection)

  // depth test, culling, blending: defaults are depth test on, no culling, no blending
  val renderState = RenderState()

  // tells materials apart when draw calls are sorted
  val id = nextResourceId()

  init {
    // create the uniforms that the shaders have in their "material" struct, and their material_... textures
    template.gatherUniforms(this)
  }

  // Draws `geometry` with this material.
  fun draw(pass : Pass, geometry : Geometry, firstInstance : Int, instanceCount : Int, vararg uniformProviders : UniformProvider) {
    // the pipeline: the shaders, the render state and the vertex layout together
    pass.encoder.setPipeline(template.pipeline(pass, geometry, renderState))
    // the few states that are not in the pipeline
    renderState.applyTo(pass)
    // uniforms and textures: from the material, and from whoever provides the rest
    template.bind(pass, this, *uniformProviders)
    geometry.draw(pass, template, firstInstance, instanceCount)
  }
}
