import vision.gears.webgpumath.*

// A geometry and the material it is drawn with.
class Mesh(val material : Material, val geometry : Geometry) : Drawable {

  override fun draw(pass : Pass, firstInstance : Int, instanceCount : Int, vararg uniformProviders : UniformProvider) {
    material.draw(pass, geometry, firstInstance, instanceCount, *uniformProviders)
  }
}
