import org.khronos.webgl.Float32Array
import org.khronos.webgl.Uint16Array
import vision.gears.webgpumath.*

class SubmeshGeometry(device : GPUDevice, val jsonMesh : JsonMesh) : Geometry() {

  init{
    // Attributes are matched by name to the inputs of the vertex shader.
    vertexAttributes["vertexPosition"] = VertexAttribute(
      createBuffer(device, Float32Array( jsonMesh.vertices ), GPUBufferUsage.VERTEX),
      "float32x3") //< three pieces of float
    vertexAttributes["vertexNormal"] = VertexAttribute(
      createBuffer(device, Float32Array( jsonMesh.normals ), GPUBufferUsage.VERTEX),
      "float32x3")
    vertexAttributes["vertexTexCoord"] = VertexAttribute(
      createBuffer(device, Float32Array( jsonMesh.texturecoords[0] ), GPUBufferUsage.VERTEX),
      "float32x2") //< two pieces of float

    val indexArray = jsonMesh.faces.flatten().toTypedArray()
    indexBuffer = createBuffer(device, Uint16Array( indexArray ), GPUBufferUsage.INDEX)
    indexFormat = "uint16"
    count = indexArray.size
  }
}
